D.terms=[
{id:"t-neogothic",name:"Неоготика",def:"Возрождение готического стиля в архитектуре XVIII–XIX веков.",ch:"Строберри Хилл Уолпола: готический загородный дом «наподобие замка из романтического прошлого», выбранный как выбирают обои.",ties:["walpole"]},
{id:"t-neogreek",name:"Неогреческий стиль",def:"Классицизм, опирающийся на формы греческих храмов, а не на римские образцы Палладио.",ch:"Кульминация в эпоху Регентства (1810–1820). Ионика в Челтнеме (ил. 312) и дорика у Соуна (ил. 313).",ties:["soane","papworth"]},
{id:"t-neoclassic",name:"Классицизм",def:"Стиль, основанный на ясных правилах античной Греции и Рима.",ch:"Стиль революционеров, мнивших себя новыми афинянами, затем стиль империи Наполеона. Монтичелло и Вашингтон в США.",ties:["jefferson","david","napoleon"]},
{id:"t-doric",name:"Дорический ордер",def:"Строгий греческий ордер колонн, знакомый по Парфенону.",ch:"Соун возрождает его «в оригинальных формах» (ил. 313; Парфенон, стр. 83, ил. 50).",ties:["soane"]},
{id:"t-ionic",name:"Ионический ордер",def:"Греческий ордер с завитками-волютами на капителях колонн.",ch:"Дорсет-Хауз в Челтнеме «в чисто ионическом стиле» греческих храмов (стр. 100, ил. 60).",ties:["papworth"]},
{id:"t-academy2",name:"Академия",def:"Учреждение, где искусство преподавали как дисциплину, а не ремесло.",ch:"К XVIII веку академии взяли на себя обучение. Они были под королевским покровительством и устраивали ежегодные выставки.",ties:["reynolds"]},
{id:"t-salon",name:"Ежегодная выставка (Салон)",def:"Регулярная публичная выставка работ членов академии, сначала в Париже, затем в Лондоне.",ch:"Художник теперь работает ради успеха на выставке, где есть риск победы эффектного над искренним. Выставки создавали и разрушали репутации.",ties:["heim","charles10"]},
{id:"t-historical",name:"Историческая живопись",def:"Картины на сюжеты истории, мифа и религии. У Копли новая основа: точное воссоздание недавнего события.",ch:"Копли «исследует» эпоху ради достоверности. Давид превращает современное событие в героическую сцену.",ties:["copley","david"]},
{id:"t-romantic",name:"Романтизм",def:"Направление, в котором художник выражает чувства и воображение, а не следует правилам.",ch:"Романтики мечтали вернуться к «Веку Веры». Тернер и Фридрих отражают чувства человека через природу.",ties:["turner","friedrich","blake"]},
{id:"t-aquatint",name:"Акватинта",def:"Техника гравюры, позволяющая передавать не только линию, но и затенённые участки.",ch:"Гойя использует её в большинстве офортов, в том числе в «Гиганте».",ties:["goya"]},
{id:"t-study",name:"Этюд с натуры",def:"Быстрая работа, выполненная с натуры и затем разрабатываемая в мастерской.",ch:"Констебл рисует этюды (ил. 324), которые нередко смелее законченных картин. Публика к ним ещё не готова.",ties:["constable"]},
{id:"t-bravura",name:"Bravura (бравура)",def:"Эффектность, попытка выйти «за пределы правды».",ch:"По Констеблу, самый большой порок эпохи. Он презирал рецепты для облаков и «скрипично-коричневый» тон первого плана.",ties:["constable"]}
];
D.idea="Французская революция 1789 года оборвала представления, которые сотни лет считались очевидными. Художник перестал быть ремесленником при дворе и стал кем-то вроде философа или поэта: он выбирает стиль, сюжет и путь сам. Одни возрождают прошлое (готика, Греция), другие создают героическую современность (Давид), третьи рисуют видения (Гойя, Блейк), четвёртые смотрят на природу (Констебл) или превращают её в бурю чувств (Тернер).";
D.blocks=[
{t:"Что было до 1789 года",s:"Новое время «начинается» с 1492 года, но искусство долго оставалось тем же: цеховое ремесло, ученики, заказы аристократии. Спорили о «красоте» (Караваджо и голландцы против Рафаэля и Рейнолдса), но были согласны в основном.",e:["caravaggio","raphael","reni","reynolds","gainsborough"],w:[]},
{t:"Стиль как выбор. Уолпол и Строберри Хилл",s:"Как герой Мольера, не знавший, что говорит прозой, художники вдруг осознали, что у них есть «стиль». Почему непременно Палладио? Уолпол строит готический замок, Чемберс изучает китайский стиль.",e:["moliere","palladio","walpole","chambers"],w:["w311"]},
{t:"Греция вместо Палладио",s:"Путешественники зарисовали афинские храмы, и они оказались совсем не похожи на гравюры Палладио. Следом за неоготикой идёт «неогрек» эпохи Регентства: ионика в Челтнеме, дорика у Соуна.",e:["soane","papworth","kent"],w:["w312","w313"]},
{t:"Разум, революция и классицизм",s:"Монтичелло Джефферсона и Вашингтон, революционная Франция как «возрождённые Афины», империя Наполеона. Параллельно у романтиков растёт интерес к готике как к «Веку Веры».",e:["jefferson","napoleon"],w:["w314"]},
{t:"Академии и выставки",s:"Живопись из ремесла превратилась в дисциплину, как философия. Академии под королевским покровительством учат на шедеврах прошлого, но покупатели хотят старых мастеров. Решение: ежегодные выставки. Их риск: победа эффектного над искренним.",e:["reynolds"],w:["wsalon"]},
{t:"Свобода выбора сюжета",s:"Раньше сюжеты были заданы: Библия, мифы, римская история, аллегории. В эпоху Французской революции художники вдруг смогли выбирать всё что угодно, от Шекспира до сегодняшних событий.",e:[],w:[]},
{t:"Американцы в Лондоне. Копли",s:"Меньшая привязанность к традиции позволила американцу написать документально точную сцену из недавней истории: Карл I и палата общин (1785). Тема понята современниками как напоминание о колониях.",e:["copley","burke","malone","george3","charles1","mirabeau"],w:["w315"]},
{t:"Давид и революционный классицизм",s:"Официальный художник революции создаёт праздники и декорации. «Смерть Марата» превращает полицейский протокол в героический образ: простота, чистота линий, ничего лишнего.",e:["david","marat","robespierre"],w:["w316"]},
{t:"Гойя: придворный и бунтарь",s:"Мастер кисти в духе Веласкеса и Тьеполо. Портреты беспощадны. Гравюры и акватинты не иллюстрируют ни Библию, ни историю: фантастические видения и обвинения.",e:["goya","ferdinand7","tiepolo","elgreco","velazquez","vandyck","titian","rembrandt"],w:["w317","w318","w319","w320"]},
{t:"Блейк: видения вместо правил",s:"Поэт-мистик, не рисовавший с натуры. Его Уризен измеряет мир циркулем, как вспышка молнии. Первый после Ренессанса, столь осознанно выступивший против норм. Признан почти через сто лет.",e:["blake","michelangelo"],w:["w321"]},
{t:"Пейзаж: Тернер и Констебл",s:"Пейзаж поднимается из второстепенного жанра. Тернер соперничает с Клодом и превращает природу в стихию. Констебл отказывается от рецептов Клода и пишет то, что видит. Фридрих даёт лирические горные пейзажи романтизма.",e:["turner","constable","friedrich","claude","vlieger","gainsborough"],w:["w322","w323","w324","w325","w326"]},
{t:"Два пути после разрыва",s:"Художники либо живописцы-поэты (Тернер, Фридрих), либо исследователи видимого мира (Констебл). Гомбрих считает второй путь значительно важнее.",e:["heim","charles10"],w:["wsalon"]}
];
