D.quiz=[
{q:"С какого года в учебниках условно отсчитывают «новое время»?",o:["1453","1492","1517","1789"],a:1,e:"Открытие Америки Колумбом. Но Гомбрих подчёркивает: настоящий слом в искусстве наступил позже, после Французской революции."},
{q:"Что построил Орас Уолпол в Строберри Хилл вместо палладианской виллы?",o:["Китайскую пагоду","Греческий храм","Готический дом, как замок из романтического прошлого","Римскую виллу с портиком"],a:2,e:"Около 1770 года это воспринималось как прихоть, а оказалось первым проявлением осознанного выбора стиля."},
{q:"Что построил Уильям Чемберс в Кью-Гарденз?",o:["Готическую башню","Китайскую пагоду","Греческий храм","Палладианский мост"],a:1,e:"Он изучал китайский стиль в архитектуре и устройстве садов."},
{q:"Какое открытие XVIII века поколебало доверие к Палладио?",o:["Находка римских вилл в Помпеях","Афинские храмы эпохи Перикла, зарисованные путешественниками","Книги Витрувия","Романские соборы"],a:1,e:"Греческие храмы выглядели иначе, чем на рисунках в книге Палладио."},
{q:"Какой стиль достиг кульминации в эпоху Регентства (1810–1820)?",o:["Неоготика","Неогреческий стиль","Барокко","Рококо"],a:1,e:"Многие курорты Англии, в частности Челтнем, лучшие примеры."},
{q:"Какой ордер возрождает Джон Соун в проекте виллы (ил. 313)?",o:["Ионический","Коринфский","Дорический","Тосканский"],a:2,e:"Именно в его оригинальных формах, как в Парфеноне."},
{q:"Почему Монтичелло Джефферсона выстроен в классицистическом стиле?",o:["Это стиль церкви","Простые правила нравились сторонникам Разума","Требование заказчика-короля","Это местная традиция Вирджинии"],a:1,e:"Такая архитектура соответствовала идеям Просвещения и республики."},
{q:"Как изменилось положение живописи в XVIII веке?",o:["Стала ремеслом цехов","Превратилась в дисциплину, которой учат в академиях","Перешла в монастыри","Стала частным делом, вне выставок"],a:1,e:"Как философия: слово «академия» восходит к роще Платона."},
{q:"Какую проблему должны были решить ежегодные выставки?",o:["Нехватку учеников","Желание заказчиков покупать только старых мастеров","Цензуру церкви","Отсутствие натурщиков"],a:1,e:"Но выставки принесли новую опасность: победу эффектного и претенциозного над простым и искренним."},
{q:"Что необычного в картине Копли о Карле I и палате общин?",o:["Религиозный сюжет","Эпизод недавней истории, воссозданный с предельной точностью","Миф об античных героях","Аллегория свободы"],a:1,e:"Сцена показана как увиденная свидетелем, после изучения костюмов и портретов депутатов."},
{q:"Кто и как изображён в «Смерти Марата» Давида?",o:["Мирабо как оратор","Марат как мученик, сохранивший реальные детали протокола","Робеспьер как жрец","Наполеон-полководец"],a:1,e:"Давид сделал сцену героической, отказавшись от лишних деталей."},
{q:"Что объединяет портреты Гойи с портретами Веласкеса и Тициана и что отличает?",o:["Нет ничего общего","Блеск шёлка и золота, но у Гойи нет жалости к модели","Религиозный фон","Одинаковое отношение к королю"],a:1,e:"Те не льстили моделям, а Гойя показывает тщеславие, жадность и пустоту."},
{q:"Как называется техника, в которой выполнено большинство офортов Гойи?",o:["Литография","Акватинта","Меццо-тинто","Ксилография"],a:1,e:"Она позволяет передавать не только линию, но и затенённые участки."},
{q:"Что за фигура изображена на гравюре Блейка «Сотворение мира»?",o:["Бог христианской традиции","Уризен, создание блейковского воображения","Платон","Ньютон"],a:1,e:"По Блейку, мир зло, а его создатель — дьявольский дух. Поэтому образ кошмарный."},
{q:"Какое условие поставил Тернер, завещая картины нации?",o:["Выставить их в Париже","Одно полотно должно всегда висеть рядом с Клодом Лорреном","Не продавать ни одной","Показывать только по праздникам"],a:1,e:"Он хотел сравняться с Клодом, если не превзойти его."},
{q:"Чем различались Тернер и Констебл в отношении к традиции?",o:["Оба подражали Клоду","Тернер соперничал с Клодом, Констебл писал то, что видит","Оба отвергали традицию","Констебл соперничал, Тернер игнорировал"],a:1,e:"Для Констебла традиция была только помехой. Он хотел писать глазами, а не глазами Клода."},
{q:"Какая картина сделала Констебла знаменитым в Париже в 1824 году?",o:["Три дерева","Повозка с сеном","Вьюга","Дидона, воздвигающая Карфаген"],a:1,e:"Простая сельская сцена: телега в броде, облака, мельница."},
{q:"Какой путь Гомбрих считает более важным после разрыва с традицией?",o:["Путь Тернера, живописцев-поэтов","Путь Констебла, стремившегося постичь окружающий мир","Путь академий","Путь Фридриха"],a:1,e:"Он пишет, что идущий путём Констебла достиг чего-то значительно более важного."}
];
